#import "SXUI.h"
#import <math.h>
BOOL SXFiniteNumber(id value){return [value isKindOfClass:NSNumber.class]&&CFGetTypeID((__bridge CFTypeRef)value)!=CFBooleanGetTypeID()&&isfinite([value doubleValue]);}
NSString *SXFormatNumber(id value,NSInteger decimals){if(!SXFiniteNumber(value))return @"—";NSNumberFormatter *formatter=[NSNumberFormatter new];formatter.locale=[NSLocale localeWithLocaleIdentifier:@"en_US"];formatter.numberStyle=NSNumberFormatterDecimalStyle;formatter.minimumFractionDigits=decimals;formatter.maximumFractionDigits=decimals;return [formatter stringFromNumber:value]?:@"—";}
NSString *SXMoney(id value,NSString *currency){return SXFiniteNumber(value)?[NSString stringWithFormat:@"%@%@",[currency isEqual:@"TWD"]?@"NT$":@"US$",SXFormatNumber(value,2)]:@"—";}
NSString *SXDateLabel(id value){NSDate *date=nil;if(SXFiniteNumber(value))date=[NSDate dateWithTimeIntervalSince1970:[value doubleValue]/1000];else if([value isKindOfClass:NSString.class]){NSISO8601DateFormatter *iso=[NSISO8601DateFormatter new];date=[iso dateFromString:value];if(!date){iso.formatOptions=NSISO8601DateFormatWithInternetDateTime|NSISO8601DateFormatWithFractionalSeconds;date=[iso dateFromString:value];}}if(!date)return @"日期未記錄";NSDateFormatter *format=[NSDateFormatter new];format.locale=[NSLocale localeWithLocaleIdentifier:@"zh_TW"];format.timeZone=[NSTimeZone timeZoneWithName:@"Asia/Taipei"];format.dateFormat=@"MM/dd HH:mm";return [format stringFromDate:date];}
NSString *SXQuoteLabel(NSDictionary *quote,BOOL stale){if(!quote)return stale?@"行情來源暫缺":@"報價待更新";NSString *time=SXFiniteNumber(quote[@"marketTime"])?SXDateLabel(@([quote[@"marketTime"] doubleValue]*1000)):([quote[@"marketDate"] isKindOfClass:NSString.class]?quote[@"marketDate"]:@"來源未提供時間");NSString *delay=SXFiniteNumber(quote[@"delayMinutes"])?([quote[@"delayMinutes"] doubleValue]>0?[NSString stringWithFormat:@"延遲 %@ 分",quote[@"delayMinutes"]]:@"即時來源"):@"延遲資訊未提供";return [NSString stringWithFormat:@"%@%@ · %@",stale?@"更新暫停 · ":@"",time,[quote[@"session"] isEqual:@"已收盤"]?@"已收盤":delay];}
UIButton *SXGlassButton(NSString *title,NSString *symbol,UIAction *action){
 UIButtonConfiguration *configuration;
#if __IPHONE_OS_VERSION_MAX_ALLOWED >= 260000
 if(@available(iOS 26.0,*))configuration=[UIButtonConfiguration clearGlassButtonConfiguration];else configuration=[UIButtonConfiguration grayButtonConfiguration];
#else
 configuration=[UIButtonConfiguration grayButtonConfiguration];
#endif
 configuration.title=title;configuration.image=symbol?[UIImage systemImageNamed:symbol]:nil;configuration.imagePadding=8;configuration.cornerStyle=UIButtonConfigurationCornerStyleCapsule;configuration.contentInsets=NSDirectionalEdgeInsetsMake(12,17,12,17);UIButton *button=[UIButton buttonWithConfiguration:configuration primaryAction:action];button.titleLabel.adjustsFontForContentSizeCategory=YES;button.accessibilityLabel=title;[button.heightAnchor constraintGreaterThanOrEqualToConstant:44].active=YES;return button;
}
void SXShowError(UIViewController *controller,NSString *title,NSString *message){if(!controller.viewIfLoaded.window)return;UIViewController *presenter=controller;while(presenter.presentedViewController&&!presenter.presentedViewController.isBeingDismissed)presenter=presenter.presentedViewController;if([presenter isKindOfClass:UIAlertController.class])return;UIAlertController *alert=[UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleDefault handler:nil]];[presenter presentViewController:alert animated:YES completion:nil];}
void SXShare(UIViewController *controller,id item){UIActivityViewController *share=[[UIActivityViewController alloc] initWithActivityItems:@[item] applicationActivities:nil];share.popoverPresentationController.sourceView=controller.view;share.popoverPresentationController.sourceRect=CGRectMake(CGRectGetMidX(controller.view.bounds),CGRectGetMidY(controller.view.bounds),1,1);[controller presentViewController:share animated:YES completion:nil];}
